SELECT CASE WHEN unit_price >= 320 THEN 'LARGE' ELSE 'SMALL' END AS unit_price_tier, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, STDDEV_SAMP(quantity) AS quantity_stddev, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50, PERCENTILE_APPROX(unit_price, 0.9) AS unit_price_p90, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items GROUP BY CASE WHEN unit_price >= 320 THEN 'LARGE' ELSE 'SMALL' END
